# One transaction; the advisory lock keeps DAGs started together from racing on CREATE.
ENSURE_TABLES_SQL = [
    "SELECT pg_advisory_xact_lock(727274)",
    BRONZE_SCHEMA_SQL,
    *OPS_DDL,
]

RUN_SQL = """
INSERT INTO ops.ingestion_runs (
    dag_id, run_id, source, source_table, target_table, pattern, status,
    watermark_from, watermark_to, rows_extracted, rows_loaded, rows_rejected,
    landing_path, started_at, extracted_at, finished_at, error
) VALUES (
    %(dag_id)s, %(run_id)s, %(source)s, %(source_table)s, %(target_table)s, %(pattern)s,
    %(status)s, %(watermark_from)s, %(watermark_to)s, %(rows_extracted)s, %(rows_loaded)s,
    %(rows_rejected)s, %(landing_path)s, %(started_at)s, %(extracted_at)s, %(finished_at)s,
    %(error)s
)
ON CONFLICT (dag_id, run_id) DO UPDATE SET
    status = EXCLUDED.status,
    watermark_from = EXCLUDED.watermark_from,
    watermark_to = EXCLUDED.watermark_to,
    rows_extracted = EXCLUDED.rows_extracted,
    rows_loaded = EXCLUDED.rows_loaded,
    rows_rejected = EXCLUDED.rows_rejected,
    landing_path = EXCLUDED.landing_path,
    started_at = EXCLUDED.started_at,
    extracted_at = EXCLUDED.extracted_at,
    finished_at = EXCLUDED.finished_at,
    error = EXCLUDED.error
"""
DELETE_REJECTS_SQL = "DELETE FROM ops.ingestion_rejects WHERE dag_id = %s AND run_id = %s"
INSERT_REJECT_SQL = """
INSERT INTO ops.ingestion_rejects (dag_id, run_id, row_number, reason, payload)
VALUES (%s, %s, %s, %s, %s::jsonb)
"""


def _upsert_run(
    cur: object,
    manifest: dict,
    status: str,
    rows_loaded: int | None = None,
    rows_rejected: int | None = None,
    error: str | None = None,
) -> None:
    run_id = manifest["run_id"]
    cur.execute(
        RUN_SQL,
        {
            "dag_id": DAG_ID,
            "run_id": run_id,
            "source": SOURCE_NAME,
            "source_table": SOURCE_TABLE,
            "target_table": f"{BRONZE_SCHEMA}.{BRONZE_NAME}",
            "pattern": PATTERN,
            "status": status,
            "watermark_from": manifest["watermark_from"],
            "watermark_to": manifest["watermark_to"],
            "rows_extracted": manifest["row_count"],
            "rows_loaded": rows_loaded,
            "rows_rejected": rows_rejected,
            "landing_path": str(_partition_dir(run_id)),
            "started_at": manifest["started_at"],
            "extracted_at": manifest["extracted_at"],
            "finished_at": None if status == "extracted" else _utcnow(),
            "error": error,
        },
    )


def _write_rejects(cur: object, run_id: str, rejects: list[tuple[int, str, str]]) -> None:
    """Replace this run's rejects, so a retry never leaves stale rows."""
    cur.execute(DELETE_REJECTS_SQL, (DAG_ID, run_id))
    cur.executemany(INSERT_REJECT_SQL, [(DAG_ID, run_id, *reject) for reject in rejects])


def _record_failure(
    conn: object, manifest: dict, rejects: list[tuple[int, str, str]], error: str
) -> None:
    """After the load rolled back: the rejects and a failed run row, in their own transaction."""
    with conn.cursor() as cur:
        _write_rejects(cur, manifest["run_id"], rejects)
        _upsert_run(cur, manifest, "failed", 0, len(rejects), error)
    conn.commit()


NEWER_LOAD_SQL = """
SELECT run_id FROM ops.ingestion_runs
WHERE dag_id = %s AND run_id <> %s AND status = 'success' AND extracted_at > %s
LIMIT 1
"""


def _check_not_stale(cur: object, manifest: dict) -> None:
    """Refuse to load a snapshot older than one already loaded by another run.

    Happens when only load_bronze of an older run is cleared after a later run succeeded.
    """
    cur.execute(NEWER_LOAD_SQL, (DAG_ID, manifest["run_id"], manifest["extracted_at"]))
    newer = cur.fetchone()
    if newer is not None:
        raise AirflowFailException(
            f"run {newer[0]!r} already loaded a newer snapshot than this run's extract. "
            "Fix: clear the whole DAG run so the extract runs again, not load_bronze alone"
        )


def _advance_state(cur: object, manifest: dict) -> None:
    """A full scan keeps no watermark."""


EXTRACT_SQL = 'SELECT "id", "customer_id", "product_id", "quantity", "total", "order_date" FROM "erp"."sales"."orders"'


@task
def extract_to_landing() -> str:
    """Copy the whole source table into this run's landing partition."""
    run_id = get_current_context()["run_id"]
    partition = _partition_dir(run_id)
    started_at = _utcnow()
    source = BaseHook.get_connection(SOURCE_CONN_ID).get_hook()
    with closing(source.get_conn()) as connection, closing(connection.cursor()) as cursor:
        cursor.execute(EXTRACT_SQL)
        columns, row_count, _ = _write_partition(partition, cursor)
    manifest = _write_manifest(partition, run_id, started_at, columns, row_count)
    with closing(PostgresHook(postgres_conn_id=TARGET_CONN_ID).get_conn()) as target:
        with target.cursor() as cur:
            _upsert_run(cur, manifest, "extracted")
        target.commit()
    return str(partition)


def _prepare_target(cur: object, run_id: str) -> None:
    """Overwrite: empty the table inside the transaction, so readers keep the old data."""
    cur.execute(PREPARE_SQL)


@task
def load_bronze() -> dict:
    """Load this run's landing partition into bronze in one transaction."""
    run_id = get_current_context()["run_id"]
    manifest = _read_manifest(_partition_dir(run_id))
    rejects: list[tuple[int, str, str]] = []
    with closing(PostgresHook(postgres_conn_id=TARGET_CONN_ID).get_conn()) as conn:
        try:
            with conn.cursor() as cur:
                _check_not_stale(cur, manifest)
                specs = _column_specs(manifest["columns"])
                cur.execute(_create_sql(specs))
                _check_drift(cur, manifest["columns"])
                _prepare_target(cur, run_id)
                loaded = _insert_rows(cur, _partition_dir(run_id), specs, run_id, rejects)
                _check_batch(cur, manifest, loaded, len(rejects), run_id)
                _write_rejects(cur, run_id, rejects)
                _advance_state(cur, manifest)
                _upsert_run(cur, manifest, "success", loaded, len(rejects))
            conn.commit()
        except QualityError as error:
            conn.rollback()
            _record_failure(conn, manifest, rejects, str(error))
            raise AirflowFailException(str(error)) from error
    return {"run_id": run_id, "rows_loaded": loaded, "rows_rejected": len(rejects)}


with DAG(
    dag_id=DAG_ID,
    description=DESCRIPTION,
    schedule=SCHEDULE,
    start_date=START_DATE,
    catchup=False,
    max_active_runs=1,
    default_args={
        "owner": OWNER,
        "retries": RETRIES,
        "retry_delay": timedelta(minutes=RETRY_DELAY_MINUTES),
    },
    tags=TAGS,
) as dag:
    ensure_tables = SQLExecuteQueryOperator(
        task_id="ensure_tables",
        conn_id=TARGET_CONN_ID,
        sql=ENSURE_TABLES_SQL,
    )
    ensure_tables >> extract_to_landing() >> load_bronze()
